// Fictional inventory fixtures share product identities and available quantities with Catalog.
const inventoryAllocations=[
  ['APP-1042','Downtown Branch','DT-01','Main Floor','FL-01',18,2,'shared'],
  ['APP-1042','North Branch','NB-02','North Stockroom','NS-02',10,1,'shared'],
  ['ACC-2180','Downtown Branch','DT-01','Main Floor','FL-01',9,1,'online_allocation'],
  ['ACC-2180','North Branch','NB-02','North Stockroom','NS-02',7,1,'shared'],
  ['APP-1168','Downtown Branch','DT-01','Main Floor','FL-01',20,2,'shared'],
  ['APP-1168','North Branch','NB-02','North Stockroom','NS-02',12,2,'shared'],
  ['APP-2074','Downtown Branch','DT-01','Main Floor','FL-01',3,1,'pos_buffer'],
  ['APP-2074','North Branch','NB-02','North Stockroom','NS-02',2,0,'pos_buffer'],
  ['BND-3011','Downtown Branch','DT-01','Main Floor','FL-01',4,1,'online_allocation'],
  ['BND-3011','North Branch','NB-02','North Stockroom','NS-02',0,0,'online_allocation'],
  ['APP-1280','Downtown Branch','DT-01','Main Floor','FL-01',4,2,'shared'],
  ['APP-1280','North Branch','NB-02','North Stockroom','NS-02',3,1,'shared']
].map(([sku,branch,branchCode,facility,facilityCode,available,reserved,mode],index)=>({sku,branch,branchCode,facility,facilityCode,available,reserved,onHand:available+reserved,reorder:8,mode,updated:index<4?'Today, 10:42 AM':'24 Sep 2026'}));
inventoryAllocations.push(...inventoryAllocations.slice(0,12).map((row,index)=>{const facility=['Annex Stockroom','Outlet Floor','Reserve Zone'][index%3],facilityCode=['AN-03','OT-04','RZ-05'][index%3],available=Math.max(0,row.available+(index%4)-1);return {...row,facility,facilityCode,available,onHand:available+row.reserved,updated:'23 Sep 2026'};}));
const inventoryMovements=[
  ['Today, 10:42 AM','APP-1042','sale_commit',-2,20,'POS-2048','Maya Bennett','DT-01'],
  ['Today, 9:18 AM','ACC-2180','adjustment_add',8,10,'ADJ-0812','Nadia Rahman','DT-01'],
  ['Yesterday, 4:35 PM','APP-1168','reservation_hold',-2,20,'ORD-1051','Ecommerce','DT-01'],
  ['Yesterday, 2:10 PM','APP-2074','adjustment_remove',-1,4,'ADJ-0807','Arif Hasan','DT-01'],
  ['23 Sep, 11:20 AM','BND-3011','set_exact',4,5,'CNT-0241','Nadia Rahman','DT-01'],
  ['22 Sep, 3:02 PM','APP-1280','reservation_release',1,7,'ORD-1047','Ecommerce','NB-02']
].map(([when,sku,type,change,after,reference,actor,facility])=>({when,sku,type,change,after,reference,actor,facility}));
inventoryMovements.push(...Array.from({length:24},(_,index)=>{const base=inventoryMovements[index%6],day=19-index%16;return {...base,when:`${day} Sep 2026, ${String(9+index%8).padStart(2,'0')}:18 AM`,change:index%2?-2:4,after:18+index%13,reference:`${index%3?'ADJ':'TRF'}-${String(812-index).padStart(4,'0')}`,actor:['Arif Rahman','Maya Chen','Jordan King'][index%3],facility:index%2?'DT-01':'NB-02'};}));
const inventoryFilters={search:'',branch:'',facility:'',location:'',mode:'',low:false,out:false,movement:''};
let inventoryPage=1,inventoryPageSize=10;
const inventoryProduct=sku=>catalogProducts.find(product=>product.sku===sku);
const inventoryProductLink=sku=>`#/app/inventory/products/${sku}`;
const inventoryTabLinks=[['overview','Overview'],['balances','Inventory Balances'],['online-stock','Channel Stock Control'],['ledger','Movement Ledger']];
function inventoryRowIsLow(row){return row.available>0&&row.available<=7;}
function inventoryVisibleRows(){return inventoryAllocations.filter(row=>{
  const product=inventoryProduct(row.sku);
  return (!inventoryFilters.search||`${product?.name} ${row.sku} ${row.branch} ${row.facility}`.toLowerCase().includes(inventoryFilters.search.toLowerCase()))
    &&(!inventoryFilters.branch||row.branchCode===inventoryFilters.branch)
    &&(!inventoryFilters.facility||row.facilityCode===inventoryFilters.facility)
    &&(!inventoryFilters.location||row.facilityCode===inventoryFilters.location)
    &&(!inventoryFilters.mode||row.mode===inventoryFilters.mode)
    &&(!inventoryFilters.low||inventoryRowIsLow(row))
    &&(!inventoryFilters.out||row.available===0);
});}
function inventoryPill(value,low=false){return `<span class="iw-qty ${value===0?'is-out':low?'is-low':''}">${value}</span>`;}
function inventoryHeader(title,subtitle,actions=''){return `<header class="iw-header"><div><span class="eyebrow">INVENTORY WORKSPACE</span><h1>${title}</h1><p>${subtitle}</p></div><div class="iw-header-actions">${actions}</div></header>`;}
function inventoryFiltersMarkup(tab){
  const options=(items,current,all)=>`<option value="">${all}</option>${items.map(([value,label])=>`<option value="${value}" ${current===value?'selected':''}>${label}</option>`).join('')}`;
  const select=(name,label,items,all)=>`<label><span>${label}</span><select data-iw-filter="${name}">${options(items,inventoryFilters[name],all)}</select></label>`;
  const branches=[['DT-01','DT-01 · Downtown Branch'],['NB-02','NB-02 · North Branch']];
  const facilities=[['FL-01','FL-01 · Main Floor'],['NS-02','NS-02 · North Stockroom']];
  let controls='';
  if(tab==='ledger')controls=select('facility','Facility',facilities,'All facilities')+select('movement','Movement type',[['adjustment_add','Adjustment - add'],['adjustment_remove','Adjustment - remove'],['set_exact','Set exact'],['reservation_hold','Reservation hold'],['reservation_release','Reservation release'],['sale_commit','Sale commit']],'All types');
  else controls=`<label class="iw-search"><span>Search</span><input type="search" id="iw-search" data-iw-filter="search" placeholder="Product, SKU, branch, or facility" value="${esc(inventoryFilters.search)}"></label>`+select('branch','Branch',branches,'All branches')+select('facility','Facility',facilities,'All facilities')+(tab==='balances'?select('location','Storage facility',facilities,'All storage facilities'):select('mode','Selling mode',[['shared','Shared'],['online_allocation','Online allocation'],['pos_buffer','POS protected']],'All modes'))+`<label class="iw-check"><input type="checkbox" data-iw-filter="low" ${inventoryFilters.low?'checked':''}>Low stock only</label><label class="iw-check"><input type="checkbox" data-iw-filter="out" ${inventoryFilters.out?'checked':''}>Out of stock only</label>`;
  return `<div class="iw-filters">${controls}<button class="btn" data-iw-clear type="button">Clear</button></div>`;
}
function inventoryPageRows(rows){const count=Math.max(1,Math.ceil(rows.length/inventoryPageSize));inventoryPage=Math.min(inventoryPage,count);return rows.slice((inventoryPage-1)*inventoryPageSize,inventoryPage*inventoryPageSize);}
function inventoryTable(headers,body,empty,total=0){return body?`<div class="iw-table-wrap"><table class="iw-table"><thead><tr>${headers.map(label=>`<th>${label}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>${window.suitePagination?window.suitePagination(total,inventoryPage,inventoryPageSize,'stock records'):''}`:`<div class="iw-empty"><strong>${empty}</strong><p>Adjust the filters to see more sample records.</p><button class="btn" data-iw-clear type="button">Clear filters</button></div>`;}
function renderInventoryOverview(){
  const tracked=inventoryAllocations.reduce((set,row)=>set.add(row.sku),new Set()).size;
  const low=inventoryAllocations.filter(inventoryRowIsLow).length;
  const out=inventoryAllocations.filter(row=>row.available===0).length;
  const reserved=inventoryAllocations.reduce((sum,row)=>sum+row.reserved,0);
  const onHand=inventoryAllocations.reduce((sum,row)=>sum+row.onHand,0);
  const stats=[['Tracked SKUs',tracked,'Across two active branches'],['Low Stock',low,'Facility balances at or below 7'],['Out Of Stock',out,'One facility needs replenishment'],['Reserved Units',reserved,'Committed to active orders'],['On Hand Units',onHand,'Physical quantity across locations']];
  return `${inventoryHeader('Inventory dashboard','A clear view of stock health, reservations, and movement across Stravix Group BD.',`<a class="btn" href="#/app/inventory/workspace/balances">Inventory Balances</a><a class="btn" href="#/app/inventory/workspace/ledger">Movement Ledger</a><a class="btn" href="#/app/inventory/transfers">Transfers</a><a class="btn primary" href="#/app/inventory/adjustments">Adjustments</a>`)}<div class="iw-stats">${stats.map(([label,value,note],i)=>`<article class="${i===1?'warn':i===2?'alert':''}"><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`).join('')}</div><div class="iw-overview-grid"><section class="iw-card"><div class="iw-card-head"><div><span class="eyebrow">REPLENISHMENT SIGNAL</span><h2>Low stock</h2></div><a href="#/app/inventory/workspace/balances?lowStockOnly=true">View balances ↗</a></div><div class="iw-summary-list">${inventoryAllocations.filter(row=>inventoryRowIsLow(row)).slice(0,5).map(row=>`<a href="${inventoryProductLink(row.sku)}"><span class="iw-product-icon">${inventoryProduct(row.sku)?.initials||'S'}</span><span class="iw-summary-copy"><strong>${esc(inventoryProduct(row.sku)?.name)}</strong><small>${row.sku} · ${row.branchCode} / ${row.facility}</small></span>${inventoryPill(row.available,true)}</a>`).join('')}</div></section><section class="iw-card"><div class="iw-card-head"><div><span class="eyebrow">ACTIVITY</span><h2>Recent movements</h2></div><a href="#/app/inventory/workspace/ledger">View ledger ↗</a></div><div class="iw-summary-list">${inventoryMovements.slice(0,5).map(entry=>`<a href="${inventoryProductLink(entry.sku)}"><span class="iw-movement-icon ${entry.change<0?'minus':'plus'}">${entry.change<0?'↘':'↗'}</span><span class="iw-summary-copy"><strong>${esc(inventoryProduct(entry.sku)?.name)}</strong><small>${entry.type.replaceAll('_',' ')} at ${entry.facility} · ${entry.when}</small></span><b class="${entry.change<0?'negative':'positive'}">${entry.change>0?'+':''}${entry.change}</b></a>`).join('')}</div></section></div>`;
}
function renderInventoryBalances(){const filtered=inventoryVisibleRows(),rows=inventoryPageRows(filtered);const body=rows.map(row=>{const product=inventoryProduct(row.sku);return `<tr><td><a class="iw-link" href="${inventoryProductLink(row.sku)}">${row.sku}</a></td><td><a class="iw-product-cell" href="${inventoryProductLink(row.sku)}"><span class="iw-product-icon">${product?.initials||'S'}</span><strong>${esc(product?.name)}</strong></a></td><td><strong>${row.branch}</strong><small>${row.branchCode}</small></td><td><strong>${row.facility}</strong><small>${row.facilityCode} · Retail</small></td><td><strong>${row.facility}</strong><small>Branch floor</small></td><td>${row.onHand}</td><td>${row.reserved}</td><td>${inventoryPill(row.available,inventoryRowIsLow(row))}</td><td>${row.reorder}</td><td><span>${row.updated}</span><a class="iw-link iw-detail-link" href="#/app/inventory/stock-card?productId=${row.sku}&facilityId=${row.facilityCode}">View details ↗</a></td></tr>`}).join('');return `${inventoryHeader('Inventory Balances','Physical stock, reservations, and reorder points by product and facility.')}<section class="iw-card iw-list-card">${inventoryFiltersMarkup('balances')}${inventoryTable(['SKU','Product','Branch','Facility','Location','On Hand','Reserved','Available','Reorder','Updated'],body,'No inventory balances matched the current filters.',filtered.length)}</section>`;}
function renderInventoryOnlineStock(){const filtered=inventoryVisibleRows(),rows=inventoryPageRows(filtered);const body=rows.map(row=>{const product=inventoryProduct(row.sku),online=row.mode==='pos_buffer'?Math.max(0,row.available-2):row.mode==='online_allocation'?Math.min(row.available,6):row.available,pos=Math.max(0,row.available-online);return `<tr><td><a class="iw-link" href="${inventoryProductLink(row.sku)}">${row.sku}</a></td><td><strong>${esc(product?.name)}</strong><small>Cap: ${product?.stock??'none'}</small></td><td><strong>${row.branch}</strong><small>${row.facilityCode} · ${row.facility}</small></td><td><strong>${row.mode.replaceAll('_',' ')}</strong><small>Enabled</small></td><td><strong>${row.mode==='online_allocation'?'6 allocated':row.mode==='pos_buffer'?'2 protected':'Shared'}</strong><small>Low threshold: 8</small></td><td>${inventoryPill(online,online<=7&&online>0)}<small>Reserved online: ${Math.min(row.reserved,1)}</small></td><td>${pos}</td><td><strong>${row.available}</strong><small>${row.onHand} on hand, ${row.reserved} reserved</small></td><td><span class="iw-badge">${product?.online==='Published'?'Published':'Hidden'}</span><small>${product?.online}</small></td><td><span class="iw-badge ${row.available===0?'out':inventoryRowIsLow(row)?'low':''}">${row.available===0?'Out of stock':inventoryRowIsLow(row)?'Low stock':'Healthy'}</span></td><td><button class="iw-link iw-edit" data-iw-edit="${row.sku}|${row.facilityCode}">Edit</button></td></tr>`}).join('');return `${inventoryHeader('Channel Stock Control','Set branch-level selling modes and see what online and POS channels can promise.')}<section class="iw-card iw-list-card">${inventoryFiltersMarkup('online-stock')}${inventoryTable(['SKU','Product','Scope','Mode','Control qty','Online','POS','Physical','Public','Status','Action'],body,'No channel stock control rows matched the current filters.',filtered.length)}</section>`;}
function renderInventoryLedger(){const filtered=inventoryMovements.filter(entry=>(!inventoryFilters.facility||entry.facility===inventoryFilters.facility)&&(!inventoryFilters.movement||entry.type===inventoryFilters.movement)),rows=inventoryPageRows(filtered);const body=rows.map(entry=>`<tr><td>${entry.when}</td><td><a class="iw-product-cell" href="${inventoryProductLink(entry.sku)}"><span class="iw-product-icon">${inventoryProduct(entry.sku)?.initials||'S'}</span><span><strong>${esc(inventoryProduct(entry.sku)?.name)}</strong><small>${entry.sku}</small></span></a></td><td><span class="iw-badge">${entry.type.replaceAll('_',' ')}</span><small>${entry.facility}</small></td><td><b class="${entry.change<0?'negative':'positive'}">${entry.change>0?'+':''}${entry.change}</b></td><td>${entry.after}</td><td><a class="iw-link" href="#/app/inventory/stock-card?productId=${entry.sku}">${entry.reference}</a></td><td>${entry.actor}</td></tr>`).join('');return `${inventoryHeader('Movement Ledger','Trace quantity changes, references, and actors across facilities.')}<section class="iw-card iw-list-card">${inventoryFiltersMarkup('ledger')}${inventoryTable(['When','Product','Movement','Change','After','Reference','Actor'],body,'No stock movement has been recorded for the current filters yet.',filtered.length)}</section>`;}
function renderInventoryWorkspace(path){const tab=path.endsWith('/balances')?'balances':path.endsWith('/online-stock')?'online-stock':path.endsWith('/ledger')?'ledger':'overview';const params=new URLSearchParams(location.hash.split('?')[1]||'');if(tab==='balances'&&params.has('lowStockOnly'))inventoryFilters.low=params.get('lowStockOnly')==='true';const content={overview:renderInventoryOverview,balances:renderInventoryBalances,'online-stock':renderInventoryOnlineStock,ledger:renderInventoryLedger}[tab]();return `<div class="inventory-workspace-mock"><nav class="iw-tabs" aria-label="Inventory workspace">${inventoryTabLinks.map(([slug,label])=>`<a href="#/app/inventory/workspace/${slug}" class="${tab===slug?'active':''}" ${tab===slug?'aria-current="page"':''}>${label}</a>`).join('')}</nav>${content}</div>`;}
root.addEventListener('input',event=>{const key=event.target.dataset.iwFilter;if(key!=='search')return;inventoryFilters.search=event.target.value;inventoryPage=1;render(true);});
root.addEventListener('change',event=>{if(event.target.matches('[data-suite-page-size]')){inventoryPageSize=Number(event.target.value)||10;inventoryPage=1;render();return;}const key=event.target.dataset.iwFilter;if(!key)return;inventoryFilters[key]=event.target.type==='checkbox'?event.target.checked:event.target.value;inventoryPage=1;render();});
root.addEventListener('click',event=>{const page=event.target.closest('[data-suite-page]');if(!page)return;if(!/^\/app\/inventory\/workspace\/(?:balances|online-stock|ledger)$/.test(pathOf()))return;inventoryPage=Number(page.dataset.suitePage)||1;render();});
window.addEventListener('hashchange',()=>{inventoryPage=1;});
root.addEventListener('click',event=>{if(event.target.closest('[data-iw-clear]')){for(const key of Object.keys(inventoryFilters))inventoryFilters[key]=typeof inventoryFilters[key]==='boolean'?false:'';render();return;}const key=event.target.closest('[data-iw-edit]')?.dataset.iwEdit;if(!key)return;const [sku,facility]=key.split('|'),row=inventoryAllocations.find(item=>item.sku===sku&&item.facilityCode===facility);if(!row)return;activeAction='Edit channel stock control';activeOverlayClass='iw-edit-drawer';activeOverlayHTML=`<div class="iw-edit-panel"><span class="eyebrow">EDITING</span><h3>${esc(inventoryProduct(sku)?.name)}</h3><p>${sku} / ${row.branchCode} / ${facility}</p><label>Selling mode<select><option>Shared</option><option>Online allocation</option><option>POS protected</option></select></label><label class="iw-check"><input type="checkbox" checked>Enabled</label><label>Online allocated quantity<input type="number" value="${Math.min(row.available,6)}"></label><label>POS protected quantity<input type="number" value="2"></label><label>Low stock threshold<input type="number" value="8"></label><div class="iw-edit-stats"><span>Physical <b>${row.available}</b></span><span>Online <b>${Math.min(row.available,6)}</b></span><span>POS <b>${Math.max(0,row.available-6)}</b></span></div><button class="btn primary" data-iw-save>Save changes</button></div>`;drawer='original';render();});
root.addEventListener('click',event=>{if(!event.target.closest('[data-iw-save]'))return;drawer='';flash('Sample channel stock controls saved.');});

const inventoryDetailTabs=[['availability','Availability'],['channel','Channel stock'],['stockCards','Stock cards'],['reservations','Reservations'],['movements','Movements'],['traceability','Traceability']];
function inventoryDetailTable(title,note,headers,body,empty){return `<section class="iw-card iw-detail-panel"><div class="iw-card-head"><div><h2>${title}</h2><p>${note}</p></div></div>${inventoryTable(headers,body,empty)}</section>`;}
function inventoryProductTab(sku,tab,rows){
  if(tab==='availability'){
    const body=rows.map(row=>{const online=row.mode==='pos_buffer'?Math.max(0,row.available-2):Math.min(row.available,6),pos=row.available-online;return `<tr class="iw-branch-row"><td><strong>${row.branchCode} · ${row.branch}</strong><small>Active branch</small></td><td>Branch total</td><td>Configured</td><td>${row.onHand}</td><td>${row.reserved}</td><td>${inventoryPill(row.available,inventoryRowIsLow(row))}</td><td>${online}</td><td>${pos}</td></tr><tr class="iw-facility-row"><td><strong>${row.facilityCode} · ${row.facility}</strong><small>Under ${row.branch}</small></td><td>Retail</td><td>Facility</td><td>${row.onHand}</td><td>${row.reserved}</td><td>${inventoryPill(row.available,inventoryRowIsLow(row))}</td><td>${online}</td><td>${pos}</td></tr>`}).join('');return inventoryDetailTable('Availability by Branch & Facility','Product-wide stock position from Inventory availability.',['Branch / Facility','Type','Policy','On Hand','Reserved','Available','Online','POS'],body,'No inventory distribution is available for this product yet.');
  }
  if(tab==='stockCards'){
    const body=rows.map(row=>`<tr><td><strong>${row.facility}</strong><small>Branch floor</small></td><td>${row.facility}</td><td>${row.branch}</td><td>${row.onHand}</td><td>${row.reserved}</td><td>${inventoryPill(row.available,inventoryRowIsLow(row))}</td><td>${row.reorder}</td><td><a class="iw-link" href="#/app/inventory/stock-card?productId=${sku}&facilityId=${row.facilityCode}">Open stock card ↗</a></td></tr>`).join('');return inventoryDetailTable('Stock Cards','Location-level balances with links into movement history.',['Location','Facility','Branch','On Hand','Reserved','Available','Reorder','Action'],body,'No stock cards found for this product.');
  }
  if(tab==='channel'){
    const body=rows.map(row=>{const online=Math.min(row.available,6);return `<tr><td><strong>${row.branch}</strong><small>${row.facilityCode} · ${row.facility}</small></td><td>${row.mode.replaceAll('_',' ')}</td><td>${row.mode==='online_allocation'?'6':'—'}</td><td>${row.mode==='pos_buffer'?'2':'—'}</td><td>8</td><td>Yes</td><td>${online}</td><td>${row.available-online}</td><td>${row.available}</td></tr>`}).join('');return inventoryDetailTable('Channel Stock Control','Read-only channel policy and sellable quantity view.',['Scope','Mode','Allocated','POS Protected','Threshold','Enabled','Online','POS','Physical'],body,'No channel stock control rows found for this product.');
  }
  if(tab==='reservations'){
    const reserved=rows.filter(row=>row.reserved>0);const body=reserved.map((row,index)=>`<tr><td>Order:ORD-${1048+index}</td><td>${row.reserved}</td><td><span class="iw-badge low">Held</span></td><td><strong>${row.branch}</strong><small>${row.facility}</small></td><td>${index?'Yesterday, 4:35 PM':'Today, 9:18 AM'}</td></tr>`).join('');return inventoryDetailTable('Reservations','Open allocations affecting available stock.',['Reference','Quantity','Status','Scope','Created'],body,'No active reservations found for this product.');
  }
  if(tab==='movements'){
    const movements=inventoryMovements.filter(entry=>entry.sku===sku);const body=movements.map(entry=>`<tr><td>${entry.when}</td><td><span class="iw-badge">${entry.type.replaceAll('_',' ')}</span></td><td><b class="${entry.change<0?'negative':'positive'}">${entry.change>0?'+':''}${entry.change}</b></td><td>${entry.after}</td><td>${entry.facility}</td><td>${entry.reference}</td><td>${entry.actor}</td></tr>`).join('');return inventoryDetailTable('Recent Movements','Latest stock ledger entries for this product.',['When','Movement','Delta','After','Location','Reference','Actor'],body,'No recent movements found for this product.');
  }
  return `<section class="iw-card iw-detail-panel"><div class="iw-card-head"><div><h2>Traceability</h2><p>Batches and serials linked to this product.</p></div></div><div class="iw-trace-grid"><article><h3>Batches</h3><div><strong>LOT-SEP26-${sku}</strong><span>Available ${rows.reduce((sum,row)=>sum+row.available,0)}</span><span class="iw-badge">Active</span></div></article><article><h3>Serials</h3><p>No serials found for this product.</p></article></div></section>`;
}
function renderInventoryProductDetail(sku){
  const product=inventoryProduct(sku),rows=inventoryAllocations.filter(row=>row.sku===sku);if(!product)return '<div class="iw-empty"><strong>Product not found</strong><a class="btn" href="#/app/inventory/workspace">Back to Inventory</a></div>';
  const params=new URLSearchParams(location.hash.split('?')[1]||'');const requested=params.get('view');const tab=inventoryDetailTabs.some(([key])=>key===requested)?requested:'availability';
  const available=rows.reduce((sum,row)=>sum+row.available,0),reserved=rows.reduce((sum,row)=>sum+row.reserved,0),online=rows.reduce((sum,row)=>sum+Math.min(row.available,6),0),pos=Math.max(0,available-online);
  const stats=[['On Hand',available+reserved],['Reserved',reserved],['Available',available],['Online',online],['POS',pos],['Branches',rows.length]];
  return `<div class="iw-product-detail"><header class="iw-detail-hero"><div><span class="eyebrow">INVENTORY PRODUCT</span><h1>${esc(product.name)}</h1><p>${sku} · ${product.category} · Stravix Group BD</p><div class="iw-hero-tags"><span>${available>7?'In stock':available>0?'Low stock':'Out of stock'}</span><span>${rows.length} active branches</span></div></div><div class="iw-detail-actions"><a href="#/app/inventory/workspace" class="btn">Inventory workspace</a><a href="#/app/inventory/adjustments" class="btn">Adjust stock</a><a href="#/app/inventory/transfers" class="btn">Transfer stock</a><a href="#/app/inventory/workspace/online-stock" class="btn primary">Channel Stock Control</a></div></header><div class="iw-stats iw-detail-stats">${stats.map(([label,value])=>`<article><span>${label}</span><strong>${value}</strong><small>${label==='Available'?'Sellable physical units':'Sample inventory position'}</small></article>`).join('')}</div><nav class="iw-tabs" aria-label="Inventory product detail sections">${inventoryDetailTabs.map(([key,label])=>`<a href="#/app/inventory/products/${sku}?view=${key}" class="${tab===key?'active':''}" ${tab===key?'aria-current="page"':''}>${label}${['availability','stockCards','channel'].includes(key)?` <span>${rows.length}</span>`:''}</a>`).join('')}</nav>${inventoryProductTab(sku,tab,rows)}</div>`;
}
function renderInventoryStockCard(){
  const params=new URLSearchParams(location.hash.split('?')[1]||'');const sku=params.get('productId')||'',facility=params.get('facilityId')||'';const row=inventoryAllocations.find(item=>item.sku===sku&&item.facilityCode===facility);const product=inventoryProduct(sku);
  const facilityOptions=[['','Select facility'],['FL-01','FL-01 · Main Floor'],['NS-02','NS-02 · North Stockroom']];
  const productOptions=[['','Select product'],...catalogProducts.filter(item=>item.stock!==null).map(item=>[item.sku,`${item.sku} · ${item.name}`])];
  const options=(items,selected)=>items.map(([value,label])=>`<option value="${value}" ${value===selected?'selected':''}>${esc(label)}</option>`).join('');
  const lookup=`<section class="iw-card iw-lookup"><div class="iw-card-head"><div><h2>Find Stock Card</h2><p>Select a branch, facility, and product, or open a stock card from a linked inventory row.</p></div></div><div class="iw-lookup-grid"><label>Branch<select data-iw-stock-field="branch"><option value="">All branches</option><option value="DT-01" ${facility==='FL-01'?'selected':''}>DT-01 · Downtown Branch</option><option value="NB-02" ${facility==='NS-02'?'selected':''}>NB-02 · North Branch</option></select></label><label>Facility<select data-iw-stock-field="facility">${options(facilityOptions,facility)}</select></label><label>Product search<input data-iw-stock-field="search" type="search" placeholder="Search SKU or product name"></label><label>Product<select data-iw-stock-field="product">${options(productOptions,sku)}</select></label><label>Variant<select><option>Base product</option><option>Sand / S</option><option>Sand / M</option></select></label><button class="btn primary" data-iw-view-card>View Stock Card</button></div></section>`;
  const stats=row?`<div class="iw-stats iw-stock-stats">${[['On Hand',row.onHand],['Reserved',row.reserved],['Available',row.available],['Reorder Point',row.reorder]].map(([label,value])=>`<article><span>${label}</span><strong>${value}</strong></article>`).join('')}</div>`:'';
  const reservations=row?.reserved?`<tr><td>Order:ORD-1048</td><td>${row.reserved}</td><td>Held</td><td>Today, 9:18 AM</td></tr>`:'';
  const movementRows=row?inventoryMovements.filter(entry=>entry.sku===sku&&entry.facility===row.branchCode).map(entry=>`<tr><td>${entry.when}</td><td>${entry.type.replaceAll('_',' ')}</td><td>${entry.change>0?'+':''}${entry.change}</td><td>${entry.after}</td><td>${entry.reference}</td><td>${entry.actor}</td></tr>`).join(''):'';
  return `<div class="iw-product-detail"><header class="iw-detail-hero"><div><span class="eyebrow">FACILITY STOCK CARD</span><h1>Movement history for one SKU at one facility</h1><p>Review live balance, active reservations, and the most recent movement ledger without leaving inventory operations.</p></div><div class="iw-detail-actions"><a class="btn" href="#/app/inventory/workspace">Back to Inventory</a></div></header>${lookup}${row?`${stats}<section class="iw-card iw-stock-title"><div class="iw-card-head"><div><h2><a href="${inventoryProductLink(sku)}">${esc(product?.name)}</a></h2><p>${sku} · ${row.facility}</p></div><span class="iw-badge">${row.branchCode}</span></div></section>${inventoryDetailTable('Active Reservations','Open allocations affecting available stock.',['Reference','Quantity','Status','Created'],reservations,'No active reservations for this SKU at this facility.')}${inventoryDetailTable('Recent Movements','Latest stock ledger entries for this stock card.',['When','Movement','Delta','After','Reference','Actor'],movementRows,'No recent movements found.')}`:'<div class="iw-stock-guidance">Select a facility and product to view a sample stock card.</div>'}</div>`;
}
let inventoryStockSelection={facility:'',product:''};
root.addEventListener('change',event=>{const key=event.target.dataset.iwStockField;if(!key)return;if(key==='branch')inventoryStockSelection.facility=event.target.value==='DT-01'?'FL-01':event.target.value==='NB-02'?'NS-02':'';else if(key==='facility'||key==='product')inventoryStockSelection[key]=event.target.value;});
root.addEventListener('click',event=>{if(!event.target.closest('[data-iw-view-card]'))return;const facility=inventoryStockSelection.facility||root.querySelector('[data-iw-stock-field="facility"]')?.value,product=inventoryStockSelection.product||root.querySelector('[data-iw-stock-field="product"]')?.value;if(!facility||!product){flash('Choose a facility and product to view the stock card.');return;}location.hash=`#/app/inventory/stock-card?productId=${product}&facilityId=${facility}`;});
